def solution():
    # Define variables name and value
    cash_flows = [20000, 30000, 50000, 60000]
    initial_investment = -100000
    guess_rate = 0.10
    tolerance = 1e-6
    max_iterations = 1000

    # Do math calculation to get the answer
    def npv(rate):
        return initial_investment + sum(
            cash_flow / ((1 + rate) ** period)
            for period, cash_flow in enumerate(cash_flows, start=1)
        )

    def npv_derivative(rate):
        return sum(
            -period * cash_flow / ((1 + rate) ** (period + 1))
            for period, cash_flow in enumerate(cash_flows, start=1)
        )

    rate = guess_rate
    for _ in range(max_iterations):
        current_npv = npv(rate)

        if abs(current_npv) < tolerance:
            break

        rate -= current_npv / npv_derivative(rate)

    # Return the MWRR as a percentage rounded to two decimal places
    answer = round(rate * 100, 2)
    return answer
